'use strict';
const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',stack:'<path d="m3 7 9-4 9 4-9 4-9-4Zm0 5 9 4 9-4M3 17l9 4 9-4"/>',scan:'<path d="M8 3H4a1 1 0 0 0-1 1v4m13-5h4a1 1 0 0 1 1 1v4M3 16v4a1 1 0 0 0 1 1h4m8 0h4a1 1 0 0 0 1-1v-4M8 12h8m-4-4v8"/>',flow:'<rect x="3" y="3" width="6" height="6" rx="1"/><rect x="15" y="15" width="6" height="6" rx="1"/><path d="M6 9v9h9M9 6h9v9"/>',chart:'<path d="M4 3v17h17M8 15v-4m5 4V7m5 8v-5"/>',building:'<rect x="5" y="3" width="14" height="18" rx="2"/><path d="M9 7h1m4 0h1m-6 4h1m4 0h1m-5 10v-6h4v6"/>',shield:'<path d="M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6l-8-3Z"/><path d="m8 12 3 3 5-6"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',external:'<path d="M14 3h7v7m0-7L10 14M10 5H5a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-5"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18m-13 4h2m4 0h2"/>',bell:'<path d="M5 17h14l-2-4V9a5 5 0 0 0-10 0v4l-2 4Zm5 3h4"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v4h16v-4"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',filter:'<path d="M3 6h18M6 12h12m-8 6h4"/>',sort:'<path d="M8 4v16m-4-4 4 4 4-4M16 4v16m-4-12 4-4 4 4"/>',left:'<path d="m14 6-6 6 6 6"/>',right:'<path d="m10 6 6 6-6 6"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.1"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z"/>',wallet:'<rect x="3" y="5" width="18" height="15" rx="2"/><path d="M3 8V5l14-2v2m-1 7h5v5h-5a2.5 2.5 0 0 1 0-5Z"/>'};
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.grid}</svg>`;
const $=selector=>document.querySelector(selector);
document.querySelectorAll('[data-icon]').forEach(el=>el.outerHTML=icon(el.dataset.icon));
const rupiah=n=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(n);
const compact=n=>`${(n/1e6).toLocaleString('id-ID',{maximumFractionDigits:1})} jt`;
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const facilities=[['RSUD Tarakan','Jakarta Pusat','B'],['RS Cendana Medika','Jakarta Selatan','C'],['RSUD Pasar Rebo','Jakarta Timur','B'],['RS Harapan Sentosa','Bekasi','C'],['RSUD Kota Bogor','Bogor','B'],['RS Bina Husada','Depok','C']];
const diagnoses=[['Pneumonia','J18.9',6200000,6],['Demam tifoid','A01.0',3800000,4],['Diabetes melitus tipe 2','E11.9',5100000,5],['Gagal jantung kongestif','I50.0',8300000,6],['Gastroenteritis','A09',2950000,3],['Persalinan sesar','O82',7400000,4],['Dengue tanpa komplikasi','A90',4600000,5],['Penyakit ginjal kronis','N18.9',9800000,7]];
const anchor=new Date('2026-10-26T12:00:00+07:00');
const claims=Array.from({length:64},(_,i)=>{const f=facilities[i%6],d=diagnoses[(i*3+Math.floor(i/8))%8],score=(i*37+83)%98,ratio=score>=70?1.42+(i%5)*.14:score>=35?1.08+(i%4)*.09:.94+(i%5)*.025;const dt=new Date(anchor);dt.setDate(dt.getDate()-Math.floor(i/5));return{id:`SEP-2610-${String(i+1).padStart(4,'0')}`,facility:f[0],city:f[1],type:f[2],diagnosis:d[0],icd:d[1],tariff:d[2],amount:Math.round(d[2]*ratio/1000)*1000,score,status:score>=85?'REJECTED':score>=35?'HOLD':'APPROVED',date:dt.toISOString().slice(0,10),los:d[3]+(score>=70?4:score>=35?2:0),normalLos:d[3],daysAgo:Math.floor(i/5)};});
const state={view:'overview',status:'all',risk:'all',search:'',period:30,page:1,descending:true};
const labels={APPROVED:'Disetujui',HOLD:'Perlu review',REJECTED:'Ditolak'};
const levels=c=>c.score>=70?'high':c.score>=35?'medium':'low';
const tag=c=>`<span class="tag ${c.status==='HOLD'?'hold':c.status==='REJECTED'?'rejected':''}">${labels[c.status]}</span>`;
const scoped=()=>claims.filter(c=>c.daysAgo<state.period);
function filtered(){return scoped().filter(c=>(state.view!=='investigations'||c.score>=70)&&(state.status==='all'||c.status===state.status)&&(state.risk==='all'||levels(c)===state.risk)&&`${c.id} ${c.facility} ${c.diagnosis} ${c.icd}`.toLowerCase().includes(state.search.toLowerCase())).sort((a,b)=>state.descending?b.score-a.score:a.score-b.score);}
function renderMetrics(){const data=scoped(),amount=data.reduce((n,c)=>n+c.amount,0),high=data.filter(c=>c.score>=70),hold=data.filter(c=>c.status==='HOLD'),exposure=high.reduce((n,c)=>n+Math.max(0,c.amount-c.tariff),0);$('#queue-count').textContent=hold.length;const metrics=[['Total nilai klaim',`Rp ${compact(amount)}`,`${data.length} klaim dalam periode ini`,'wallet',false],['Perlu ditinjau',hold.length,`<b>${Math.round(hold.length/data.length*100)}%</b> dari seluruh klaim`,'stack',false],['Sinyal risiko tinggi',high.length,'Skor risiko 70 atau lebih','scan',false],['Selisih perlu diperiksa',`Rp ${compact(exposure)}`,'Di atas tarif · klaim risiko tinggi','shield',true]];$('#metrics').innerHTML=metrics.map(([label,value,sub,glyph,dark])=>`<article class="metric ${dark?'featured':''}"><div class="metric-head"><span>${label}</span>${icon(glyph)}</div><strong class="metric-value">${value}</strong><span class="metric-sub">${sub}</span></article>`).join('');renderCharts(data);}
function renderCharts(data){$('#chart-total').textContent=data.length;$('#chart-range').textContent=state.period===7?'20–26 Okt 2026':'13–26 Okt · 2 hari/bar';const buckets=Array.from({length:7},()=>({all:0,reviewed:0}));data.forEach(c=>{const bucket=state.period===7?6-c.daysAgo:Math.min(6,6-Math.floor(c.daysAgo/2));if(bucket<0)return;buckets[bucket].all++;if(c.status!=='HOLD')buckets[bucket].reviewed++;});const max=Math.max(...buckets.map(b=>b.all),10);$('#bar-chart').innerHTML=buckets.map((b,i)=>`<div class="bar-column" title="${b.all} klaim; ${b.reviewed} sudah ditinjau"><div class="bar" style="--height:${b.all/max*90}%;--reviewed:${b.all?b.reviewed/b.all*100:0}%"><div class="bar-dark"></div></div><span class="bar-label">${state.period===7?20+i:13+i*2} Okt</span></div>`).join('');$('#bar-chart').setAttribute('aria-label',`Grafik tujuh kelompok tanggal: ${buckets.map(b=>`${b.all} klaim, ${b.reviewed} ditinjau`).join('; ')}`);const groups=[['Rendah','low','#cce2d2'],['Sedang','medium','#83ae91'],['Tinggi','high','#206b4a']],counts=groups.map(g=>data.filter(c=>levels(c)===g[1]).length);let offset=0;const circumference=2*Math.PI*61;$('#donut-svg').innerHTML=groups.map((g,i)=>{const length=counts[i]/data.length*circumference;const html=`<circle cx="80" cy="80" r="61" fill="none" stroke="${g[2]}" stroke-width="13" stroke-dasharray="${Math.max(0,length-5)} ${circumference}" stroke-dashoffset="${-offset}" stroke-linecap="round"/>`;offset+=length;return html;}).join('');$('#risk-percent').textContent=`${Math.round(counts[2]/data.length*100)}%`;$('#risk-legend').innerHTML=groups.map((g,i)=>`<div><i class="legend-dot" style="background:${g[2]}"></i>${g[0]}<b>${counts[i]}</b></div>`).join('');}
function renderTable(){const list=filtered(),pages=Math.max(1,Math.ceil(list.length/6));state.page=Math.min(state.page,pages);const start=(state.page-1)*6,page=list.slice(start,start+6);$('#result-count').textContent=list.length;$('#claim-rows').innerHTML=page.length?page.map(c=>`<tr><td><span class="claim-id">${c.id}</span><span class="claim-diagnosis">${c.icd} · ${c.diagnosis}</span></td><td><div class="hospital"><span class="hospital-icon">${icon('building')}</span><div>${c.facility}<small>${c.city} · Tipe ${c.type}</small></div></div></td><td>${rupiah(c.amount)}</td><td><div class="risk-score ${levels(c)}"><span class="score-bar" aria-hidden="true">${Array.from({length:5},(_,i)=>`<i class="${i<Math.ceil(c.score/20)?'on':''}"></i>`).join('')}</span>${c.score}<span class="sr-only"> dari 99</span></div></td><td>${tag(c)}</td><td><button class="icon-button" data-detail="${c.id}" aria-label="Lihat detail klaim ${c.id}">${icon('arrow')}</button></td></tr>`).join(''):`<tr><td colspan="6" class="empty"><strong>Tidak ada klaim yang cocok.</strong>Coba kata kunci lain atau ubah filter risiko dan status.</td></tr>`;$('#page-info').textContent=list.length?`Menampilkan ${start+1}–${Math.min(start+6,list.length)} dari ${list.length} klaim`:'0 klaim ditemukan';$('#page-number').textContent=`${state.page} / ${pages}`;$('#previous-page').disabled=state.page===1;$('#next-page').disabled=state.page>=pages;$('#sort-risk').setAttribute('aria-label',`Urutkan risiko ${state.descending?'terendah':'tertinggi'} dahulu`);document.querySelector('th:has(#sort-risk)').setAttribute('aria-sort',state.descending?'descending':'ascending');}
const views={overview:['Overview','Satu pandangan untuk setiap klaim yang perlu perhatian Anda.'],claims:['Antrean klaim','Telusuri pengajuan, periksa temuan, dan tentukan prioritas review.'],investigations:['Investigasi risiko','Fokus pada klaim dengan skor risiko 70 atau lebih.'],pipeline:['Pipeline audit','Pahami alur pemeriksaan dari aturan hingga rekomendasi.'],reports:['Laporan','Bawa ringkasan data ke proses review berikutnya.']};
function setView(view){if(!views[view])return;state.view=view;state.status='all';state.risk='all';state.search='';state.page=1;$('#search').value='';$('#risk-filter').value='all';document.querySelectorAll('[data-status]').forEach(b=>{b.classList.toggle('selected',b.dataset.status==='all');b.setAttribute('aria-pressed',b.dataset.status==='all');});const [title,subtitle]=views[view];$('#breadcrumb-current').textContent=title;$('#page-title').innerHTML=`${title}<span class="title-dot">.</span>`;$('#page-subtitle').textContent=subtitle;document.title="SIKEPO";$('#overview-content').hidden=view!=='overview';$('#queue-section').hidden=!['overview','claims','investigations'].includes(view);$('#pipeline-section').hidden=view!=='pipeline';$('#reports-section').hidden=view!=='reports';$('#table-title').firstChild.textContent=view==='investigations'?'Klaim dengan sinyal risiko tinggi':view==='claims'?'Seluruh pengajuan klaim':'Klaim yang perlu perhatian';$('#all-claims').hidden=view!=='overview';document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);if(b.dataset.view===view)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});$('#sidebar').classList.remove('open');$('#menu-button').setAttribute('aria-expanded','false');history.replaceState(null,'',`#${view}`);renderTable();window.scrollTo({top:0,behavior:'instant'});}
function showDetail(id){const c=claims.find(c=>c.id===id);if(!c)return;const ratio=(c.amount/c.tariff).toFixed(2).replace('.',',');const finding=c.score>=70?`Pengajuan ${ratio}× tarif acuan. Selisih ${rupiah(c.amount-c.tariff)} perlu dicocokkan dengan rincian pelayanan.`:c.score>=35?`Pengajuan ${ratio}× tarif acuan. Periksa kelengkapan dokumen sebelum review lanjutan.`:'Nilai pengajuan mendekati tarif acuan pada data simulasi ini.';$('#detail-body').innerHTML=`<h2 id="detail-title">${c.id}</h2><div class="detail-meta">${tag(c)}<span class="tag neutral">Data sintetis</span></div><div class="detail-facts"><div><small>Fasilitas kesehatan</small><strong>${c.facility}</strong></div><div><small>Diagnosis</small><strong>${c.icd} · ${c.diagnosis}</strong></div><div><small>Biaya diajukan</small><strong>${rupiah(c.amount)}</strong></div><div><small>Tarif acuan INA CBG</small><strong>${rupiah(c.tariff)}</strong></div><div><small>Durasi rawat / acuan simulasi</small><strong>${c.los} hari / ${c.normalLos} hari</strong></div><div><small>Skor risiko ilustratif</small><strong>${c.score} / 99</strong></div></div><div class="findings"><div>${icon('scan')}<div><strong>Sinyal finansial</strong>${finding}</div></div><div>${icon('calendar')}<div><strong>Durasi perawatan</strong>${c.los>c.normalLos?`Durasi ${c.los-c.normalLos} hari di atas acuan simulasi. Cocokkan dengan kondisi klinis dan resume medis.`:'Durasi sesuai acuan pada skenario simulasi ini.'}</div></div><div>${icon('flow')}<div><strong>Jejak pipeline</strong>Panel ini menampilkan contoh hasil audit. Mesin A1, IsolationForest A2, dan LLM A3 belum dijalankan.</div></div></div><p class="detail-notice">Temuan adalah ilustrasi untuk desain panel. Status dihasilkan dari aturan demo dan bukan keputusan klinis, pembayaran, atau pembuktian fraud.</p>`;$('#claim-dialog').showModal();}
let toastTimeout;function notify(message){clearTimeout(toastTimeout);$('#toast').textContent=message;$('#toast').hidden=false;toastTimeout=setTimeout(()=>$('#toast').hidden=true,4000);}
function exportCSV(){const data=state.view==='reports'?scoped():filtered();if(!data.length){notify('Tidak ada klaim untuk diekspor. Ubah filter terlebih dahulu.');return;}const cells=v=>`"${String(v).replace(/"/g,'""')}"`;const rows=[['ID klaim','Tanggal','Faskes','Kota','Diagnosis','ICD10','Pengajuan IDR','Tarif IDR','Risiko','Status','Jenis data'],...data.map(c=>[c.id,c.date,c.facility,c.city,c.diagnosis,c.icd,c.amount,c.tariff,c.score,c.status,'SINTETIS'])];const blob=new Blob(['\uFEFF'+rows.map(r=>r.map(cells).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8;'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`sikepo-demo-${state.view}-${state.period}hari.csv`;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);notify(`${data.length} klaim sintetis diekspor ke CSV.`);}
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>setView(b.dataset.view)));
document.querySelectorAll('[data-status]').forEach(b=>b.addEventListener('click',()=>{state.status=b.dataset.status;state.page=1;document.querySelectorAll('[data-status]').forEach(el=>{el.classList.toggle('selected',el===b);el.setAttribute('aria-pressed',el===b);});renderTable();}));
$('#search').addEventListener('input',e=>{state.search=e.target.value;state.page=1;renderTable();});
$('#risk-filter').addEventListener('change',e=>{state.risk=e.target.value;state.page=1;renderTable();});
$('#period').addEventListener('change',e=>{state.period=Number(e.target.value);state.page=1;renderMetrics();renderTable();});
$('#sort-risk').addEventListener('click',()=>{state.descending=!state.descending;state.page=1;renderTable();});
$('#previous-page').addEventListener('click',()=>{state.page--;renderTable();});$('#next-page').addEventListener('click',()=>{state.page++;renderTable();});
$('#claim-rows').addEventListener('click',e=>{const b=e.target.closest('[data-detail]');if(b)showDetail(b.dataset.detail);});
$('#all-claims').addEventListener('click',()=>setView('claims'));$('#start-audit').addEventListener('click',()=>{setView('claims');document.querySelector('[data-status="HOLD"]').click();});
$('#export-top').addEventListener('click',exportCSV);$('#export-report').addEventListener('click',exportCSV);
$('#about-button').addEventListener('click',()=>$('#about-dialog').showModal());$('#close-about').addEventListener('click',()=>$('#about-dialog').close());$('#close-detail').addEventListener('click',()=>$('#claim-dialog').close());
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
$('#notification-button').addEventListener('click',()=>notify(`${scoped().filter(c=>c.status==='HOLD').length} klaim sintetis menunggu review pada periode ini.`));
$('#menu-button').addEventListener('click',()=>{$('#sidebar').classList.toggle('open');$('#menu-button').setAttribute('aria-expanded',$('#sidebar').classList.contains('open'));});
document.addEventListener('click',e=>{if(!e.target.closest('#sidebar, #menu-button')){$('#sidebar').classList.remove('open');$('#menu-button').setAttribute('aria-expanded','false');}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#sidebar').classList.remove('open');$('#menu-button').setAttribute('aria-expanded','false');}if(e.key==='/'&&!e.ctrlKey&&!e.metaKey&&!e.altKey&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!document.querySelector('dialog[open]')){e.preventDefault();if(!['overview','claims','investigations'].includes(state.view))setView('claims');$('#search').focus();}});
renderMetrics();setView(location.hash.slice(1)||'overview');
